'use strict';
const SAVE_KEY='kora-bay-v1';
const INITIAL=()=>({version:1,name:'New neighbour',money:1800,minutes:480,day:1,energy:85,hunger:72,mood:80,skill:0,shifts:0,friends:0,home:'room',location:'home',visited:['home'],furniture:[{uid:'starter-bed',type:'bed',x:0,y:0,rot:0}],roomStyle:'sand',relationships:{},phoneNotes:'',vehicles:[],activeTransport:'walk',activityStats:{},journal:[{day:1,minutes:480,text:'Arrived in Kora Bay with a shared room, ₭1,800, and a fresh start.'}]});
let state=INITIAL(), selected='home', travelling=false, toastTimer, pendingRent=0;
try{const saved=JSON.parse(localStorage.getItem(SAVE_KEY));if(saved&&saved.version===1&&['money','minutes','day','energy','hunger','mood','skill','shifts','friends'].every(k=>Number.isFinite(saved[k]))&&saved.money>=0&&saved.day>=1&&saved.minutes>=0&&saved.minutes<1440&&['room','studio'].includes(saved.home)&&typeof saved.name==='string'&&Array.isArray(saved.visited)&&Array.isArray(saved.journal))state={...state,...saved};}catch(e){}
const PLACES=[
 {id:'home',name:'Palm House',type:'A place to recharge',icon:'⌂',color:'#eadfcf',x:3,y:6,w:2,d:2,height:54,roof:'#bc8068',wall:'#eddec1',description:'Your little corner of the city. Rest up, reset, and make tomorrow count.'},
 {id:'market',name:'Sunbird Market',type:'Work & everyday essentials',icon:'▥',color:'#e6d8bf',x:6,y:2,w:2,d:2,height:28,roof:'#c89665',wall:'#ebd9b3',description:'Bright stalls, good food, and a steady stream of neighbours. There is always a pair of hands needed.'},
 {id:'cafe',name:'Mango & Co.',type:'Good food, good company',icon:'☕',color:'#e6d7cb',x:11,y:6,w:2,d:2,height:39,roof:'#bd8065',wall:'#f0e2c8',description:'Something warm on the stove. Someone with a story. Stay for a bite or earn your keep behind the counter.'},
 {id:'library',name:'The Reading Room',type:'Learn something new',icon:'▤',color:'#dce2cf',x:6,y:11,w:2,d:2,height:58,roof:'#86977b',wall:'#e6dfcb',description:'A quiet place to get a little further. Build your skills to unlock better-paying shifts.'},
 {id:'waterfront',name:'Driftwood Walk',type:'Take a little breather',icon:'≈',color:'#d2e3df',x:15,y:11,w:2,d:2,height:8,roof:'#bcad88',wall:'#c9bd9b',description:'Salt in the air. Boats on the horizon. A good place to slow down and meet someone new.'},
 {id:'studio',name:'Olive Court',type:'Your next chapter',icon:'⌑',color:'#e1e4d0',x:11,y:2,w:2,d:2,height:72,roof:'#8d9d7f',wall:'#e8dfbf',description:'Sunlit windows, a tiny balcony, and a key with only your name on it. A studio of your very own.'}
];
if(!PLACES.some(p=>p.id===state.location))state.location='home';selected=state.location;
const $=s=>document.querySelector(s);const cash=n=>'₭'+Math.floor(n).toLocaleString();const clamp=n=>Math.min(100,Math.max(0,n));
function timeLabel(m){const h=Math.floor(m/60);return `${h%12||12}:${String(m%60).padStart(2,'0')} ${h>=12?'PM':'AM'}`;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));$('#saveLabel').textContent='Your story saves automatically';return true;}catch(e){$('#saveLabel').textContent='Saving unavailable in this browser';return false;}}
function log(text){state.journal.unshift({day:state.day,minutes:state.minutes,text});state.journal=state.journal.slice(0,60);}
function advance(minutes,energy=-3,hunger=-4,mood=0){state.energy=clamp(state.energy+energy);state.hunger=clamp(state.hunger+hunger);state.mood=clamp(state.mood+mood);state.minutes+=minutes;while(state.minutes>=1440){state.minutes-=1440;state.day++;if((state.day-1)%7===0){const rent=state.home==='studio'?1400:900;const paid=Math.min(rent,state.money);state.money-=paid;pendingRent+=rent-paid;log(`${cash(paid)} paid toward weekly rent.`);}}if(pendingRent){state.money=Math.max(0,state.money-pendingRent);toast(`Rent day: your savings covered part of the rent. Your landlord waived ${cash(pendingRent)} this time.`);log(`The landlord waived ${cash(pendingRent)} of rent. A fresh chance to get on track.`);pendingRent=0;}save();render();}
function runAction(action){if(action==='enter-scene')return window.openActivityScene?.(selected);if(window.playSceneAction?.(action))return;return applyGameAction(action);}
function applyGameAction(action){if(travelling)return;const beforeMoney=state.money;let msg='';switch(action){
 case 'furnish':return window.openApartment?.();
 case 'market-work':case 'cafe-work':{if(state.energy<25||state.hunger<20)return toast('Get some food and rest first. A shift needs 25 energy and 20 fullness.');const pay=(action==='cafe-work'?650:480)+state.skill*100;state.money+=pay;state.shifts++;advance(240,-25,-22,-5);msg=`Shift done. ${cash(pay)} earned — one step closer to your own place.`;log(`Worked at ${PLACES.find(p=>p.id===state.location).name} and earned ${cash(pay)}.`);break;}
 case 'meal':{const cost=state.location==='market'?120:180;if(state.money<cost)return toast(`You need ${cash(cost)} for this meal. A snack at home is free.`);state.money-=cost;advance(30,5,42,8);msg='A proper meal. Things already feel a little brighter.';log(`Enjoyed a meal at ${PLACES.find(p=>p.id===state.location).name}.`);break;}
 case 'snack':advance(20,0,22,0);msg='A little bread and tea from the shared pantry. You can always eat at home.';break;
 case 'sleep':advance(480,90,-28,15);msg='Eight hours later, a fresh start.';log('Got a good night’s sleep at home.');break;
 case 'nap':advance(120,38,-10,6);msg='A little rest goes a long way. Energy restored.';break;
 case 'study':if(state.skill>=5)return toast('You have mastered all five skill levels in this first chapter.');if(state.energy<15)return toast('You need at least 15 energy to focus. Rest at home first.');state.skill++;advance(120,-15,-12,6);msg=`Skill level ${state.skill}! Every shift now pays ${cash(state.skill*100)} extra.`;log(`Reached skill level ${state.skill} at The Reading Room.`);break;
 case 'walk':advance(60,-5,-6,26);msg='Sea air and a slower pace. Just what you needed.';break;
 case 'chat':return window.meetNeighbour?.();
 case 'move':if(state.home==='studio')return toast('You already have your own studio. Welcome home.');if(state.money<5000)return toast(`You need ${cash(5000-state.money)} more for the studio deposit. Keep going!`);state.money-=5000;state.home='studio';advance(60,-5,-5,30);log('Moved into a studio at Olive Court. A key of my own!');msg='Your own front door. Your own little world. You did it!';break;
 }save();render();toast(msg);if(beforeMoney<5000&&state.money>=5000&&state.home==='room')setTimeout(()=>toast('You did it — ₭5,000 saved! Visit Olive Court to move into your studio.'),5200);}
function actionButton(label,key,detail,secondary=false,disabled=false){return `<button class="action ${secondary?'secondary':''}" data-action="${key}" ${disabled?'disabled':''}><span>${label}</span><small>${detail} ↗</small></button>`;}
function renderLocation(){const p=PLACES.find(p=>p.id===selected);const here=state.location===selected;const plan=window.getTravelPlan?.(selected)||{verb:'Walk',minutes:15};let actions='';if(!here)actions=actionButton(travelling?'On your way…':plan.verb+' here','travel',plan.minutes+' min',false,travelling)+(plan.reason?`<p class="action-note">${plan.reason}</p>`:'');else switch(p.id){case 'home':actions=actionButton('Get some sleep','sleep','8 hr · +90 energy')+actionButton('A quick nap','nap','2 hr · +38 energy',true)+actionButton('Bread & tea','snack','20 min · free',true);break;case 'market':actions=actionButton('Help at the market','market-work',`4 hr · +${cash(480+state.skill*100)}`)+actionButton('Grab a hot meal','meal','30 min · ₭120',true);break;case 'cafe':actions=actionButton('Work a café shift','cafe-work',`4 hr · +${cash(650+state.skill*100)}`)+actionButton('Sit down for lunch','meal','30 min · ₭180',true);break;case 'library':actions=actionButton('Build your skills','study','2 hr · free',false,state.skill>=5)+`<p class="action-note">Skill level ${state.skill}/5 · +₭100 per shift, per level</p>`;break;case 'waterfront':actions=actionButton('Take a seaside walk','walk','1 hr · +26 mood')+actionButton('Say hello to someone','chat','45 min · free',true);break;case 'studio':actions=state.home==='studio'?actionButton('Sleep in your studio','sleep','8 hr · +90 energy')+actionButton('Bread & tea','snack','20 min · free',true):actionButton('Make it your own','move','₭5,000 deposit')+'<p class="action-note">Weekly rent: ₭1,400 · first due on day 8, then every 7 days</p>';}
 if(here&&(p.id==='studio'&&state.home==='studio'||p.id==='home'&&state.home==='room'))actions=actionButton('Furnish my place','furnish','Enter & decorate')+actions;
 if(here&&(p.id!=='studio'||state.home==='studio'))actions=actionButton(p.id==='home'||p.id==='studio'?'Enter my home':p.id==='waterfront'?'Explore the waterfront':'Go inside','enter-scene','Play here')+(p.id==='waterfront'?actionButton('Go swimming','swim','45 min',true):'')+actions;
 $('#locationPanel').innerHTML=`<p class="location-kicker"><span>${here?'YOU ARE HERE':'YOUR NEXT STOP'}</span><span>${here?'●':'↗'}</span></p><div class="location-title"><span class="location-icon" style="background:${p.color}">${p.icon}</span><div><h3>${p.name}</h3><p>${p.type}</p></div></div><p class="location-description">${p.description}</p>${actions}`;
 $('#locationPanel').querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>b.dataset.action==='travel'?travel(selected):runAction(b.dataset.action));}
function render(){const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];$('#money').textContent=cash(state.money);$('#clock').textContent=`${days[(state.day-1)%7]}, ${timeLabel(state.minutes)}`;$('#dayLabel').textContent=`DAY ${String(state.day).padStart(2,'0')}`;$('#sunIcon').textContent=state.minutes>=1080||state.minutes<360?'☾':'☀';$('#profileName').textContent=state.name;$('#housingLabel').textContent=state.home==='studio'?'Your own studio':'Shared room';$('#rentLabel').textContent=state.home==='studio'?'₭1,400 / week':'₭900 / week';$('#currentLocation').textContent=PLACES.find(p=>p.id===state.location).name;
 $('#needs').innerHTML=[['energy','ϟ','Energy',state.energy],['hunger','♧','Fullness',state.hunger],['mood','☺','Mood',state.mood]].map(([id,icon,label,value])=>`<div class="need ${id}"><span class="need-icon">${icon}</span><div><div class="need-label"><span>${label}</span><small>${value<25?'Needs a little care':value>65?'Looking good':'Doing okay'}</small></div><div class="need-track"><span style="width:${value}%;${value<25?'background:#c47f5f':''}"></span></div></div><span>${value}%</span></div>`).join('');
 $('#places').innerHTML=PLACES.map(p=>`<button class="place ${selected===p.id?'selected':''}" data-place="${p.id}" aria-pressed="${selected===p.id}"><span class="place-icon" style="background:${p.color}">${p.icon}</span><span><b>${p.name}</b><small>${p.type}</small></span><span>↗</span></button>`).join('');$('#places').querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>selectPlace(b.dataset.place));
 const progress=state.home==='studio'?100:Math.min(100,Math.floor(state.money/50));$('#goalProgress').style.width=progress+'%';$('#goalAmount').textContent=state.home==='studio'?'A key of your own':cash(state.money)+' saved';$('#goalPercent').textContent=progress+'%';$('#goalText').textContent=state.home==='studio'?'You made it. This is just the beginning.':'Save ₭5,000 to move into a studio.';const ride=window.getTravelPlan?.();if(ride)$('#transportStatus').textContent=ride.name+' · '+ride.minutes+' min per trip';renderLocation();window.renderResidents?.();window.drawCity?.();}
function selectPlace(id){if(travelling)return toast('Almost there. Enjoy the walk.');selected=id;render();if(innerWidth<650)$('#locationPanel').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});}
async function travel(id){if(travelling||!PLACES.some(p=>p.id===id))return false;if(id===state.location)return true;window.closeActivityScene?.();const plan=window.getTravelPlan?.(id)||{mode:'walk',minutes:15,energy:2,hunger:2,fuel:0};travelling=true;renderLocation();try{if(window.animateTravel)await window.animateTravel(state.location,id,plan.mode);state.location=id;const vehicle=state.vehicles.find(v=>v.id===plan.mode);if(vehicle&&plan.fuel)vehicle.fuel=Math.max(0,vehicle.fuel-plan.fuel);if(!state.visited.includes(id)){state.visited.push(id);log(`Discovered ${PLACES.find(p=>p.id===id).name}.`);}travelling=false;advance(plan.minutes,-plan.energy,-plan.hunger,1);toast(`${plan.reason?plan.reason+' ':''}Welcome to ${PLACES.find(p=>p.id===id).name}.`);return true;}catch(e){window.resetPlayer?.();toast('Your trip could not finish. Try choosing the destination again.');return false;}finally{travelling=false;renderLocation();}}
function openDialog(title,html){$('#dialog').classList.remove('room-mode');$('#dialogEyebrow').textContent=title;$('#dialogContent').innerHTML=html;$('#dialog').showModal();}
function showHelp(){openDialog('WELCOME TO KORA BAY',`<h2>Your next chapter starts here.</h2><p>This is your city to figure out, one small step at a time.</p><ul><li>Pick a building on the map or a place below it. Choose <b>Walk here</b>, then try an activity.</li><li>Earn money at Sunbird Market or Mango & Co. Study at the library to earn more per shift.</li><li>Food restores fullness. Sleep restores energy. The waterfront lifts your mood.</li><li>Open <b>My phone &rarr; Bay Rides</b> to buy a bicycle, motorbike, or car. Choose a destination to ride there. Refuel in Bay Rides or choose walking whenever you like.</li><li>Your room has free bread and tea, so you can always get back on your feet.</li><li>Choose <b>My apartment</b> to enter your home, walk around, sit, sleep, cook, shower, read, tidy, or dance. Use <b>Arrange furniture</b> inside to decorate.</li><li>At Driftwood Walk, choose <b>Go swimming</b> or <b>Explore the waterfront</b>. Swim, fish, relax, jog, and stretch in the activity scene.</li><li>Click a walking neighbour or their card below the map to talk. They remember you, and later conversations grow your friendship.</li><li>Save <b>₭5,000</b> and visit Olive Court to rent your own studio. Your furniture moves with you.</li><li>Rent is collected on day 8, then every 7 days. Game time moves only when you take an action; residents can walk while you watch.</li></ul><p>Progress saves in this browser. A fictional city, a story of your own.</p><button class="action" id="startExploring">Let's explore <span>↗</span></button>`);$('#startExploring').onclick=()=>$('#dialog').close();}
$('#helpBtn').onclick=showHelp;$('#mapHelp').onclick=showHelp;$('#closeDialog').onclick=()=>$('#dialog').close();$('#dialog').onclick=e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#dialog').close();}};
$('#journalBtn').onclick=()=>{openDialog('MY JOURNAL',`<h2>The little things add up.</h2><p>${state.shifts} shifts worked · Skill level ${state.skill} · ${state.visited.length}/6 places discovered</p><div id="entries"></div>`);for(const entry of state.journal){const el=document.createElement('div');el.className='journal-entry';const time=document.createElement('small');time.textContent=`DAY ${entry.day} · ${timeLabel(entry.minutes)}`;const text=document.createElement('p');text.textContent=entry.text;el.append(time,text);$('#entries').append(el);}};
$('#exploreBtn').onclick=()=>{$('#dialog').close();$('#city').focus();};
$('#profileBtn').onclick=()=>{openDialog('MAKE YOURSELF AT HOME','<h2>What should we call you?</h2><p>A new city. Same you. Or a whole new you.</p><form id="nameForm"><label for="characterName">Your name</label><input id="characterName" maxlength="24" autocomplete="given-name" required><button class="action" type="submit">This is me <span>↗</span></button></form>');$('#characterName').value=state.name==='New neighbour'?'':state.name;$('#nameForm').onsubmit=e=>{e.preventDefault();state.name=$('#characterName').value.trim().slice(0,24)||'New neighbour';save();render();$('#dialog').close();toast(`Welcome to the neighbourhood, ${state.name}.`);};};
$('#resetBtn').onclick=()=>{if(travelling)return toast('Finish your walk before starting a new story.');openDialog('A FRESH START','<h2>Start a new story?</h2><p>This replaces the progress saved in this browser. You’ll begin again at Palm House with ₭1,800.</p><div class="choice-row"><button id="cancelReset" class="action secondary">Keep my story</button><button id="confirmReset" class="action">Start fresh ↗</button></div>');$('#cancelReset').onclick=()=>$('#dialog').close();$('#confirmReset').onclick=()=>{state=INITIAL();selected='home';travelling=false;window.closeActivityScene?.();window.resetLife?.();window.migrateActivities?.();save();render();window.resetPlayer?.();$('#dialog').close();toast('A fresh start. The city is waiting.');};};
render();save();
